function minArrayLength(nums, k) {
  const memo = new Map();
  const search = (arr) => {
    const key = arr.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = arr.length;
    for (let i = 0; i + 1 < arr.length; i++) {
      const product = arr[i] * arr[i + 1];
      if (product <= k) best = Math.min(best, search([...arr.slice(0, i), product, ...arr.slice(i + 2)]));
    }
    memo.set(key, best);
    return best;
  };
  return search(nums);
}

