function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const zeroChance = rand() < 0.3 ? 0.15 : 0;
    const top = rand() < 0.5 ? 4 : 12;
    const nums = Array.from({ length: n }, () => (rand() < zeroChance ? 0 : pick(1, top)));
    return [nums, pick(1, 40)];
  }
  const n = 2000;
  const k = rand() < 0.5 ? pick(1, 1000) : pick(1, 1000000000);
  const nums = Array.from({ length: n }, () => {
    const r = rand();
    if (r < 0.6) return pick(1, 9);
    if (r < 0.9) return pick(1, 1000);
    return pick(1, 1000000000);
  });
  if (rand() < 0.15) nums[pick(0, n - 1)] = 0;
  return [nums, k];
}
